export const themes=rows.map((r,index)=>{const [id,name,category,pl,en,layout,accent,bg,font,headlinePl,headlineEn,descPl,descEn,articlePl,articleEn]=r;return {id,name,category,index,topic:{pl,en},layout,accent,bg,font,headline:{pl:headlinePl,en:headlineEn},description:{pl:descPl,en:descEn},article:{pl:articlePl,en:articleEn},image:assets[id]?.url||'',source:assets[id]?.source||'',pages:['home','article','product','about','contact','404'],version:'1.0.0'};});
export function filterThemes({query='',category='all',favorites=null,sort='curated'}={}){const q=query.toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/ł/g,'l');let list=themes.filter(t=>(category==='all'||t.category===category)&&(!favorites||favorites.includes(t.id))&&([t.name,t.topic.pl,t.topic.en,t.description.pl,t.description.en].join(' ').toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/ł/g,'l').includes(q)));if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
